function OverseaManageCustomerInfoDialog:RefreshBtnRedDot()
    local redPoint = false
    for i, v in pairs(self.areaInfo) do
        redPoint = self:GetTabRedPointByIndex(i)
        if redPoint then
            break
        end
    end
    GameUtils.UpdateServerRedPointData({cafeVisitorCollection = redPoint and 0 or -1})
end

function OverseaManageCustomerInfoDialog:FreshTab()
    ---@type CommonTabToggleLeft
    local env = CfUtils.GetLuaScr(self.CommonTabToggleLeft.gameObject, CommonTabToggleLeftPath)
    if isNull(env) then return end
    local toggleData = self:InitToggleData()
    env:SetAfterAction(function(index)
        print('--->>', index)
        local vo = ActionUtils.GetRegionPrimaryMapVo(index + 1 )
        if vo then
            if self.openArea == checkNumber(vo.id) then return end
            self.openArea = checkNumber(vo.id)
            self.curHead = nil
            self:RefreshRightNodeShow()
        end
    end)
    env:FillToggles(toggleData,self.openArea)
end

function OverseaManageCustomerInfoDialog:FreshRedPoint()
    self:FreshTabRedPoint()
    self:FreshHeadRedPoint()
end

function OverseaManageCustomerInfoDialog:FreshHeadRedPoint()
    local data = self.collectData[self.openArea].visitors[self.curHead]
    local isHeadHave = self:IsHaveRedPoint(data.favoriteGoods) or self:IsHaveRedPoint(data.exclusiveEvents)
    self.headNodeEnv[self.curHead]:RefreshRedPoint(isHeadHave)
end

function OverseaManageCustomerInfoDialog:IsHeadIconHaveRedPoint(index)
    local data = self.collectData[self.openArea].visitors[index]
    local isHeadHave = self:IsHaveRedPoint(data.favoriteGoods) or self:IsHaveRedPoint(data.exclusiveEvents)
    return isHeadHave
end

function OverseaManageCustomerInfoDialog:FreshTabRedPoint()
    local status = self:GetTabRedPointByIndex(self.openArea)
    ---@type CommonTabToggleLeft
    local env = CfUtils.GetLuaScr(self.CommonTabToggleLeft.gameObject, CommonTabToggleLeftPath)
    if isNull(env) then return end
    env:FreshTabRedPointByIndex(self.openArea - 1,status)
end

function OverseaManageCustomerInfoDialog:GetTabRedPointByIndex(index)
    local data = self.collectData[index]
    local redPoint = false
    if not isNull(data) then
        local visitors = data.visitors
        for i, v in pairs(visitors) do
            local isGoodsHave = self:IsHaveRedPoint(v.favoriteGoods)
            if isGoodsHave then
                redPoint = true
                break
            end

            local isEventHave = self:IsHaveRedPoint(v.exclusiveEvents)
            if isEventHave then
                redPoint = true
                break
            end
        end
    end
    return redPoint
end

function OverseaManageCustomerInfoDialog:IsHaveRedPoint(goods)
    local redPoint = false
    for i, v in pairs(goods) do
        if v.status == EventStatus.NoGet then
            redPoint = true
            break
        end
    end
    return redPoint
end

function OverseaManageCustomerInfoDialog:RefreshRightNodeShow()
    if not isNull(self.collectData) then
        local data = self.collectData[self.openArea].visitors
        for i, v in pairs(self.headNodeEnv) do
            local guestData = data[i]
            if not isNull(guestData) then
                local curHead = isNull(self.curHead) and self.preHeadNode or self.curHead
                v:RefreshHeadNodeShow(guestData,curHead)
                local status = self:IsHeadIconHaveRedPoint(i)
                v:RefreshRedPoint(status)
                KTool.SetActive(v.controller.gameObject,true)
            else
                KTool.SetActive(v.controller.gameObject,false)
            end
        end
    end
    self:RefreshAreaName()
end

function OverseaManageCustomerInfoDialog:RefreshAreaName()
    ----@type RegionPrimaryMapVo
    local vo = ActionUtils.GetRegionPrimaryMapVo(self.openArea)
    if not isNull(vo) then
        CfUtils.FillText(self.AreaTxt,vo.name)
    end
end

function OverseaManageCustomerInfoDialog:InitToggleData()
    local allVos = CfUtils.GetCf(AutoIds.IdSetting6071,"MaidCoffeeGuestCollectionVo",true)
    for i, v in pairs(allVos) do
        if not self.areaInfo[v.map] then
            self.areaInfo[v.map] = {}
        end
        table.insert(self.areaInfo[v.map],v)
    end

    local toggleData = {}
    for i = 1, #self.areaInfo do
        ---是否解锁的逻辑
        local vo = ActionUtils.GetRegionPrimaryMapVo(i)
        local isUnlock, description = ActionUtils.IsUnlockRegionalPoint(vo.id)
        local redPointStatus = isUnlock and self:GetTabRedPointByIndex(i) or false
        table.insert(toggleData, { text = vo.name, lock = (not isUnlock), textDefStatus = isUnlock and 1 or 3, redPointStatus = redPointStatus, func = function(data, index)
            if vo then
                if isUnlock then return 1 else
                    GameUtils.Toast(description)
                    return 0
                end
            end
            return 0
        end })

        if isUnlock and self.openArea == 0 then
            self.openArea = checkNumber(vo.id)
        end
    end

    return toggleData
end

function OverseaManageCustomerInfoDialog:OnHeadNodeClick(index,headData,vo)
    if index == self.curHead then
        return
    end
    self:DoHeadNodeSelect(self.curHead)
    self.curHead = index
    self:RefreshNodeShow(headData,vo)
end

function OverseaManageCustomerInfoDialog:OnGoodsNodeClick(index,goodsId,npcId)
    GameUtils.Request(Interfaces.MaidCoffeeGuestUnLockGood,{visitorId = npcId,goodsId = goodsId},function(request,response)
        if checkNumber(response.errCode) == 0 then
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            if not isNull(vo) then
                GameUtils.Toast(localize("解锁了喜好【_name_】",{_name_ = vo.name }))
            end
            self.collectData[self.openArea].visitors[self.curHead].favoriteGoods[index].status = 2
            self.goodsNodeEnv[index]:RefreshStatus()
            self:FreshRedPoint()
            CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("OverseaManageCustomerInfoDialog")
        end
    end)
end

function OverseaManageCustomerInfoDialog:OnEventNodeClick(index,eventId,npcId)
    GameUtils.Request(Interfaces.MaidCoffeeGuestUnLockEvent,{visitorId = npcId,eventId = eventId},function(request,response)
        if checkNumber(response.errCode) == 0 then
            local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
            local vo = MaidCoffeeUtils.GetGuestEventVo(eventId)
            if not isNull(vo) then
                GameUtils.Toast(localize("解锁了话题【_name_】",{_name_ = vo.name }))
            end
            self.collectData[self.openArea].visitors[self.curHead].exclusiveEvents[index].status = 2
            self.eventNodeEnv[index]:RefreshStatus()
            self:FreshRedPoint()
            CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("OverseaManageCustomerInfoDialog")
        end
    end)
end

function OverseaManageCustomerInfoDialog:DoHeadNodeSelect(index)
    if not isNull(index) then
        self.headNodeEnv[index]:DoSelect()
    end
end

function OverseaManageCustomerInfoDialog:RefreshNodeShow(headData,vo)
    CfUtils.FillText(self.TextName,vo.name)
    CfUtils.FillText(self.TextNumber,headData.visitedTimes)
    self:SetEventNodeShow(headData.exclusiveEvents,headData.visitorId)
    self:SetLikeGoodShow(headData.favoriteGoods,headData.visitorId)
end

function OverseaManageCustomerInfoDialog:SetEventNodeShow(events,npcId)
    for i = 1, EventNodeCount do
        local data = events[i]
        if not isNull(data) then
            self.eventNodeEnv[i]:RefreshShow(data,npcId)
            KTool.SetActive(self.eventNodeEnv[i].controller.gameObject,true)
        else
            KTool.SetActive(self.eventNodeEnv[i].controller.gameObject,false)
        end
    end
end

function OverseaManageCustomerInfoDialog:SetLikeGoodShow(goods,npcId)
    for i = 1, LikeNodeCount do
        local data = goods[i]
        if not isNull(data) then
            self.goodsNodeEnv[i]:RefreshShow(data,npcId)
            KTool.SetActive(self.goodsNodeEnv[i].controller.gameObject,true)
        else
            KTool.SetActive(self.goodsNodeEnv[i].controller.gameObject,false)
        end
    end
end

return OverseaManageCustomerInfoDialog